### User Consent Management

**Consent Framework**:
```typescript
class ConsentManagementService {
  async recordConsent(userId: string, consentType: ConsentType): Promise<void> {
    const consent = {
      userId,
      type: consentType,
      granted: true,
      timestamp: new Date(),
      ipAddress: this.getClientIP(),
      userAgent: this.getUserAgent(),
    };

    await this.storeConsent(consent);
  }

  async withdrawConsent(userId: string, consentType: ConsentType): Promise<void> {
    await this.updateConsent(userId, consentType, false);
    await this.initiateDataDeletion(userId, consentType);
  }
}

enum ConsentType {
  DATA_PROCESSING = 'data_processing',
  MARKETING = 'marketing',
  ANALYTICS = 'analytics',
  THIRD_PARTY_SHARING = 'third_party_sharing',
}
```

